 Box("Staff doorway left trim",new Vector3(-28.12f,1.75f,-6),new Vector3(.14f,3.5f,.3f),gold);Box("Staff wall lower panel",new Vector3(-19,.65f,-6.15f),new Vector3(17.8f,1.1f,.035f),dark);Box("Staff wall lower trim",new Vector3(-19,1.22f,-6.17f),new Vector3(17.8f,.04f,.035f),gold);
 Box("VIP doorway left trim",new Vector3(-10.15f,1.7f,3.05f),new Vector3(.35f,3.4f,.15f),gold);Box("VIP doorway right trim",new Vector3(-10.15f,1.7f,7.95f),new Vector3(.35f,3.4f,.15f),gold);
