 public static void Rebuild(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();foreach(var g in m.stealth.guards){var mod=g.GetComponent<NavMeshModifier>();if(!mod)mod=g.gameObject.AddComponent<NavMeshModifier>();mod.ignoreFromBuild=true;EditorUtility.SetDirty(mod);}var surface=m.interior.GetComponent<NavMeshSurface>();surface.BuildNavMesh();var saved=AssetDatabase.LoadAssetAtPath<NavMeshData>(Art+"VenueNavigation.asset");var generated=surface.navMeshData;EditorUtility.CopySerialized(generated,saved);surface.RemoveData();surface.navMeshData=saved;surface.AddData();UnityEngine.Object.DestroyImmediate(generated);EditorUtility.SetDirty(saved);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);Validate();VenueFinaleBuilder.Preview();}
 public static void Validate(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();var s=m.stealth;string log="Venue stealth saved paths\n";var points=new[]{m.inside}.Concat(s.approachRoute).Concat(new[]{m.interiorExit}).ToArray();for(int i=1;i<points.Length;i++){var path=new NavMeshPath();bool ok=NavMesh.CalculatePath(points[i-1].position,points[i].position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;log+=(ok?"PASS ":"FAIL ")+points[i-1].name+" -> "+points[i].name+"\n";}foreach(var g in s.guards){var p=new NavMeshPath();bool ok=NavMesh.CalculatePath(g.posts[0].position,g.posts[1].position,NavMesh.AllAreas,p)&&p.status==NavMeshPathStatus.PathComplete;log+=(ok?"PASS ":"FAIL ")+g.name+" patrol\n";}File.WriteAllText("Logs/Venue-stealth-geometry.txt",log);if(log.Contains("FAIL"))throw new Exception(log);}
